/* With GX_ENABLE_CANVAS_PARTIAL_FRAME_BUFFER, the refresh of a partial canvas
   whose dirty list holds transparent widgets, and a memory define on a canvas
   with no display.

   A partial canvas is refreshed in strips that fit its memory; after each strip
   the display's buffer toggle copies it out. The test's display has a toggle
   that copies each strip into a whole frame, so the frame shows the result of a
   refresh as a screen would. Three windows draw known colors: the root fills
   all of itself, a transparent window inside it draws only its children, and a
   window inside that fills only its inner part, so its border shows what is
   behind it.

   A transparent widget's area is redrawn from its first ancestor that is not
   transparent. The refresh climbs to that ancestor for each dirty widget that
   is transparent, through transparent parents, or to the top if there is none:
   1. The inner window is marked dirty, then made transparent before the
      refresh, so the dirty list holds a transparent widget whose parent is
      transparent too. Over the inner window's area the frame must show the
      root's color with the inner window's inner part on it, and nothing else
      may change.
   2. The root is made transparent and marked dirty: no ancestor, so it is
      redrawn itself. The whole frame must show the root, with the inner
      window's inner part.

   gx_canvas_memory_define refuses a canvas with no display. Every canvas
   gx_canvas_create makes has one, so the test sets the canvas's display
   pointer to GX_NULL itself (fault injection on a struct field), calls the
   define, and puts the pointer back. No execution produces such a canvas. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_display.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_partial_frame_buffer_16bpp_transparent_refresh_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

#define TEST_WIDTH        40
#define TEST_HEIGHT       30
#define TEST_PIXELS       (TEST_WIDTH * TEST_HEIGHT)
/* Brush colors are given as RGB and converted by the display: these two are
   exact in 565rgb.  */
#define TEST_ROOT_RGB     0xff0000
#define TEST_ROOT_COLOR   0xf800
#define TEST_INNER_RGB    0x00ff00
#define TEST_INNER_COLOR  0x07e0
#define TEST_STALE        0x5555

static UINT           failed_tests = 0;

static TX_THREAD      test_thread;
static ULONG          test_thread_stack[8192 / sizeof(ULONG)];

static GX_DISPLAY     test_display;
static GX_CANVAS      test_canvas;
static USHORT         test_memory[TEST_PIXELS / 4];
static USHORT         test_frame[TEST_PIXELS];
static USHORT         test_model[TEST_PIXELS];
static GX_WINDOW_ROOT test_root;
static GX_WINDOW      test_middle;
static GX_WINDOW      test_inner;
static GX_RECTANGLE   test_inner_part;

/* Copy the strip just drawn from the partial canvas memory into the frame.  */
static VOID test_toggle(GX_CANVAS *canvas, GX_RECTANGLE *dirty)
{
INT x;
INT y;

    for (y = dirty -> gx_rectangle_top; y <= dirty -> gx_rectangle_bottom; y++)
    {
        for (x = dirty -> gx_rectangle_left; x <= dirty -> gx_rectangle_right; x++)
        {
            test_frame[y * TEST_WIDTH + x] =
                test_memory[(y - canvas -> gx_canvas_memory_offset_y) * canvas -> gx_canvas_memory_width +
                            (x - canvas -> gx_canvas_memory_offset_x)];
        }
    }
}

static UINT test_display_setup(GX_DISPLAY *display)
{
    _gx_display_driver_565rgb_setup(display, (VOID *)1, test_toggle);
    return GX_SUCCESS;
}

static VOID test_fill(GX_RECTANGLE *area, GX_COLOR color)
{
    gx_context_raw_brush_define(color, color, GX_BRUSH_SOLID_FILL);
    gx_context_brush_width_set(0);
    gx_canvas_rectangle_draw(area);
}

static VOID test_root_draw(GX_WIDGET *widget)
{
    test_fill(&widget -> gx_widget_size, TEST_ROOT_RGB);
    gx_widget_children_draw(widget);
}

static VOID test_middle_draw(GX_WIDGET *widget)
{
    gx_widget_children_draw(widget);
}

static VOID test_inner_draw(GX_WIDGET *widget)
{
    test_fill(&test_inner_part, TEST_INNER_RGB);
    gx_widget_children_draw(widget);
}

/* The model: the stale frame, with the given area redrawn.  */
static VOID test_model_build(GX_RECTANGLE *redrawn)
{
INT      index;
GX_POINT point;

    for (index = 0; index < TEST_PIXELS; index++)
    {
        point.gx_point_x = (GX_VALUE)(index % TEST_WIDTH);
        point.gx_point_y = (GX_VALUE)(index / TEST_WIDTH);
        if (!gx_utility_rectangle_point_detect(redrawn, point))
        {
            test_model[index] = TEST_STALE;
        }
        else if (gx_utility_rectangle_point_detect(&test_inner_part, point))
        {
            test_model[index] = TEST_INNER_COLOR;
        }
        else
        {
            test_model[index] = TEST_ROOT_COLOR;
        }
    }
}

static VOID test_refresh_check(char *label, GX_RECTANGLE *redrawn)
{
INT index;

    test_model_build(redrawn);
    EXPECT_EQ(GX_SUCCESS, gx_system_canvas_refresh());
    for (index = 0; index < TEST_PIXELS; index++)
    {
        if (test_frame[index] != test_model[index])
        {
            printf("%s: frame (%d, %d) 0x%04x, model 0x%04x\n", label, index % TEST_WIDTH, index / TEST_WIDTH,
                   test_frame[index], test_model[index]);
            failed_tests++;
            return;
        }
    }
}

static VOID test_stale(VOID)
{
INT index;

    for (index = 0; index < TEST_PIXELS; index++)
    {
        test_frame[index] = TEST_STALE;
    }
}

static VOID test_thread_entry(ULONG id)
{
GX_RECTANGLE size;
GX_DISPLAY  *display;
GX_COLOR    *memory;
ULONG        memory_size;

    gx_system_initialize();

    EXPECT_EQ(GX_SUCCESS, gx_display_create(&test_display, "test_display", test_display_setup, TEST_WIDTH, TEST_HEIGHT));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_canvas, "test_canvas", &test_display, GX_CANVAS_MANAGED | GX_CANVAS_VISIBLE,
                                           TEST_WIDTH, TEST_HEIGHT, GX_NULL, 0));

    /* A canvas with no display, by fault injection.  */
    display = test_canvas.gx_canvas_display;
    test_canvas.gx_canvas_display = GX_NULL;
    EXPECT_EQ(GX_INVALID_DISPLAY, gx_canvas_memory_define(&test_canvas, (GX_COLOR *)test_memory, sizeof(test_memory)));
    test_canvas.gx_canvas_display = display;
    memory = test_canvas.gx_canvas_memory;
    memory_size = test_canvas.gx_canvas_memory_size;
    EXPECT_EQ(0, memory_size);
    EXPECT_EQ(GX_TRUE, memory == GX_NULL);

    EXPECT_EQ(GX_SUCCESS, gx_canvas_memory_define(&test_canvas, (GX_COLOR *)test_memory, sizeof(test_memory)));
    EXPECT_EQ(GX_CANVAS_PARTIAL_FRAME_BUFFER, test_canvas.gx_canvas_status & GX_CANVAS_PARTIAL_FRAME_BUFFER);

    gx_utility_rectangle_define(&size, 0, 0, TEST_WIDTH - 1, TEST_HEIGHT - 1);
    EXPECT_EQ(GX_SUCCESS, gx_window_root_create(&test_root, "test_root", &test_canvas, GX_STYLE_NONE, GX_ID_NONE, &size));
    gx_utility_rectangle_define(&size, 5, 4, 34, 25);
    EXPECT_EQ(GX_SUCCESS, gx_window_create(&test_middle, "test_middle", &test_root, GX_STYLE_TRANSPARENT, GX_ID_NONE, &size));
    gx_utility_rectangle_define(&size, 10, 8, 25, 21);
    EXPECT_EQ(GX_SUCCESS, gx_window_create(&test_inner, "test_inner", &test_middle, GX_STYLE_NONE, GX_ID_NONE, &size));
    gx_utility_rectangle_define(&test_inner_part, 13, 11, 22, 18);
    gx_widget_draw_set(&test_root, test_root_draw);
    gx_widget_draw_set(&test_middle, test_middle_draw);
    gx_widget_draw_set(&test_inner, test_inner_draw);
    EXPECT_EQ(GX_SUCCESS, gx_widget_show(&test_root));

    /* The first refresh draws the whole frame.  */
    test_stale();
    gx_utility_rectangle_define(&size, 0, 0, TEST_WIDTH - 1, TEST_HEIGHT - 1);
    test_refresh_check("first refresh", &size);

    /* 1. A dirty widget made transparent, under a transparent parent.  */
    test_stale();
    gx_system_dirty_mark(&test_inner);
    EXPECT_EQ(GX_SUCCESS, gx_widget_style_add(&test_inner, GX_STYLE_TRANSPARENT));
    test_refresh_check("transparent dirty widget", &test_inner.gx_widget_size);

    /* 2. A transparent root.  */
    test_stale();
    EXPECT_EQ(GX_SUCCESS, gx_widget_style_add(&test_root, GX_STYLE_TRANSPARENT));
    gx_system_dirty_mark(&test_root);
    test_refresh_check("transparent root", &test_root.gx_widget_size);

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

